function toUnitSeed(book: RemainingBookSeed): HistoricalUnitSeed {
  const unitId = book.id + "-u01";
  const lessons: HistoricalLessonSeed[] = book.anchors.map((anchor, index) => {
    const [title, label, startChapter, endChapter, conceptTitle, teaching, formation, correct, d1, d2, d3] = anchor;
    const conceptId = book.id + "-c" + String(index + 1).padStart(2, "0");
    return {
      title,
      reference: [label, startChapter, 1, endChapter],
      concept: [conceptId, conceptTitle],
      teaching,
      formation,
      question: [
        "Qual afirmação corresponde ao conteúdo estudado em " + label + "?",
        correct, d1, d2, d3,
        teaching
      ],
      fill: [
        "A síntese fiel da passagem é: ",
        correct,
        ".",
        d1, d2, d3,
        formation
      ]
    };
  });
  return {
    id: unitId,
    title: book.unitTitle,
    subtitle: book.subtitle,
    chapters: Array.from({ length: book.chapterCount }, (_, index) => index + 1),
    lessons
  };
}

export interface RemainingJourneyBook {
  id: string;
  title: string;
  shortTitle: string;
  chapterCount: number;
  units: Unit[];
}

export const remainingOldTestamentBooks: RemainingJourneyBook[] = BOOKS.map((book) => ({
  id: book.id,
  title: book.title,
  shortTitle: book.shortTitle,
  chapterCount: book.chapterCount,
  units: buildHistoricalUnits(book.id, book.title, [toUnitSeed(book)])
}));
